         goto reject_sample;
    }
    if (dt_config.stop_rate_t_s <= 0.0 || dt_config.restart_rate_t_s <= 0.0 || 
        dt_config.fine_enter_rate_t_s <= 0.0 || dt_config.fine_exit_rate_t_s <= 0.0) {
         goto reject_sample;
    }
    if (dt_config.stop_rate_t_s >= dt_config.restart_rate_t_s || 
        dt_config.restart_rate_t_s >= dt_config.fine_enter_rate_t_s || 
        dt_config.fine_enter_rate_t_s >= dt_config.fine_exit_rate_t_s) {
         goto reject_sample;
    }
    if (dt_config.required_good < 1 || dt_config.required_good > 20 ||
        dt_config.max_bad < 1 || dt_config.max_bad > 20) {
         goto reject_sample;
    }

    // 2. Enable Check
    if (!dt_input.enable) {
        dt_state.mode = DT_OFF;
        dt_state.good = 0;
        dt_state.bad = 0;
        dt_state.filter.initialized = 0;
        dt_state.previous_dipole_a_m2.x = 0.0;
        dt_state.previous_dipole_a_m2.y = 0.0;
        dt_state.previous_dipole_a_m2.z = 0.0;

        dt_output.mode = dt_state.mode;
        dt_output.good = dt_state.good;
        dt_output.bad = dt_state.bad;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.filter_primed_this_cycle = 0;
        dt_output.field_magnitude_t = 0.0;
        dt_output.rate_norm_t_s = 0.0;
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        return;
    }

    // 3. Input Validity
    if (dt_input.field_body_t == NULL) {
        goto reject_sample;
    }

    adcs_vec3_t current_field = *dt_input.field_body_t;
    double time_s = dt_input.time_s;

    // 4. Gap Check & Priming
    int need_prime = 0;
    if (!dt_state.filter.initialized) {
        need_prime = 1;
    } else {
        double dt = time_s - dt_state.filter.previous_time_s;
        if (dt <= 0.0 || !isfinite(dt) || dt > dt_config.max_sample_gap_s) {
            need_prime = 1;
        }
    }

    if (need_prime) {
        // Reset and Re-prime
        dt_state.mode = DT_COARSE;
        dt_state.good = 0;
        dt_state.bad = 0; 

        // Update filter to prime it
        dt_state.filter.previous_field_t = current_field;
        dt_state.filter.previous_time_s = time_s;
        dt_state.filter.initialized = 1;
        dt_state.filtered_rate_t_s.x = 0.0;
        dt_state.filtered_rate_t_s.y = 0.0;
        dt_state.filtered_rate_t_s.z = 0.0;

        // Clear stored dipole immediately
        dt_state.previous_dipole_a_m2.x = 0.0;
        dt_state.previous_dipole_a_m2.y = 0.0;
        dt_state.previous_dipole_a_m2.z = 0.0;

        dt_output.mode = dt_state.mode;
        dt_output.good = dt_state.good;
        dt_output.bad = dt_state.bad;
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.filter_primed_this_cycle = 1;
        dt_output.field_magnitude_t = adcs_vec3_norm(&current_field);
        dt_output.rate_norm_t_s = 0.0;
        dt_output.rate_t_s.x = 0.0;
        dt_output.rate_t_s.y = 0.0;
        dt_output.rate_t_s.z = 0.0;
        dt_output.dipole_a_m2.x = 0.0;
        dt_output.dipole_a_m2.y = 0.0;
        dt_output.dipole_a_m2.z = 0.0;
        return;
    }

    // 5. Filter Update
    adcs_bdot_state_t filter_copy = dt_state.filter;
    adcs_vec3_t filtered_rate;
    adcs_status_t status = adcs_bdot_update(&filter_copy, &current_field, time_s, dt_config.filter_alpha, &filtered_rate);
    if (status != ADCS_OK) {
        goto reject_sample;
    }
    dt_state.filter = filter_copy;
    dt_state.filtered_rate_t_s = filtered_rate;

    // 6. Field Magnitude Check
    double field_mag = adcs_vec3_norm(&current_field);
    if (field_mag < dt_config.minimum_field_t || field_mag > dt_config.maximum_field_t) {
        goto reject_sample;
    }

    // 7. Mode Logic
    adcs_actuator_command_t dipole_cmd;
    double gain = 0.0;

    // Initialize output fields
    dt_output.field_magnitude_t = field_mag;
    dt_output.rate_norm_t_s = adcs_vec3_norm(&filtered_rate);
    dt_output.rate_t_s = filtered_rate;

    // Determine Gain and Potential Mode Transition
    if (dt_state.mode == DT_COARSE) {
        gain = dt_config.coarse_gain_a_m2_s_t;
        if (dt_output.rate_norm_t_s <= dt_config.fine_enter_rate_t_s) {
            dt_state.mode = DT_FINE;
            gain = dt_config.fine_gain_a_m2_s_t;
        }
    } else if (dt_state.mode == DT_FINE) {
        gain = dt_config.fine_gain_a_m2_s_t;
        if (dt_output.rate_norm_t_s > dt_config.fine_exit_rate_t_s) {
            dt_state.mode = DT_COARSE;
            gain = dt_config.coarse_gain_a_m2_s_t;
        }
    } else if (dt_state.mode == DT_COMPLETE) {
        // In COMPLETE, we command zero unless restarting
        if (dt_output.rate_norm_t_s >= dt_config.fine_exit_rate_t_s) {
             dt_state.mode = DT_COARSE;
             gain = dt_config.coarse_gain_a_m2_s_t;
        } else if (dt_output.rate_norm_t_s >= dt_config.restart_rate_t_s) {
             dt_state.mode = DT_FINE;
             gain = dt_config.fine_gain_a_m2_s_t;
        } else {
             // Stay in COMPLETE, command zero
             gain = 0.0;
        }
    } else {
        // Default to Coarse
        dt_state.mode = DT_COARSE;
        gain = dt_config.coarse_gain_a_m2_s_t;
    }

    // Generate Dipole
    if (gain > 0.0) {
        status = adcs_bdot_dipole(&current_field, &filtered_rate, gain, dt_config.max_dipole_a_m2, &dipole_cmd);
        if (status != ADCS_OK) {
             dipole_cmd.command.x = 0.0;
             dipole_cmd.command.y = 0.0;
             dipole_cmd.command.z = 0.0;
             dipole_cmd.saturated_axes = 0U;
        }
    } else {
        dipole_cmd.command.x = 0.0;
        dipole_cmd.command.y = 0.0;
        dipole_cmd.command.z = 0.0;
        dipole_cmd.saturated_axes = 0U;
    }

    // 8. Slew Limiting
    adcs_vec3_t limited_dipole;
    uint32_t sat_mask = dipole_cmd.saturated_axes;
    uint32_t slew_mask = 0U;

    double diffs[3];
    diffs[0] = dipole_cmd.command.x - dt_state.previous_dipole_a_m2.x;
    diffs[1] = dipole_cmd.command.y - dt_state.previous_dipole_a_m2.y;
    diffs[2] = dipole_cmd.command.z - dt_state.previous_dipole_a_m2.z;

    double max_slew = dt_config.max_dipole_slew_a_m2_per_cycle;

    limited_dipole.x = 0.0;
    limited_dipole.y = 0.0;
    limited_dipole.z = 0.0;

    for (int i = 0; i < 3; i++) {
        double prev = (i == 0) ? dt_state.previous_dipole_a_m2.x : ((i == 1) ? dt_state.previous_dipole_a_m2.y : dt_state.previous_dipole_a_m2.z);
        double curr = (i == 0) ? dipole_cmd.command.x : ((i == 1) ? dipole_cmd.command.y : dipole_cmd.command.z);
        double diff = curr - prev;

        if (diff > max_slew) {
            if (i == 0) limited_dipole.x = prev + max_slew;
            else if (i == 1) limited_dipole.y = prev + max_slew;
            else limited_dipole.z = prev + max_slew;
            slew_mask |= (uint32_t)(1U << i);
        } else if (diff < -max_slew) {
            if (i == 0) limited_dipole.x = prev - max_slew;
            else if (i == 1) limited_dipole.y = prev - max_slew;
            else limited_dipole.z = prev - max_slew;
            slew_mask |= (uint32_t)(1U << i);
        } else {
            if (i == 0) limited_dipole.x = curr;
            else if (i == 1) limited_dipole.y = curr;
            else limited_dipole.z = curr;
        }
    }

    // 9. Complete Mode Zeroing
    if (dt_state.mode == DT_COMPLETE) {
        limited_dipole.x = 0.0;
        limited_dipole.y = 0.0;
        limited_dipole.z = 0.0;
        slew_mask = 0U;
    }

    // 10. Good/Bad Counters and State Updates
    if (dt_state.mode == DT_COARSE || dt_state.mode == DT_FINE) {
        if (dt_output.rate_norm_t_s <= dt_config.stop_rate_t_s) {
            dt_state.good++;
            if (dt_state.good >= dt_config.required_good) {
                dt_state.mode = DT_COMPLETE;

                // Clear stored dipole immediately
                dt_state.previous_dipole_a_m2.x = 0.0;
                dt_state.previous_dipole_a_m2.y = 0.0;
                dt_state.previous_dipole_a_m2.z = 0.0;

                // Publish zero
                limited_dipole.x = 0.0;
                limited_dipole.y = 0.0;
                limited_dipole.z = 0.0;
                slew_mask = 0U;
            }
        } else {
            dt_state.good = 0;
        }
    }

    // Update Previous Dipole for Next Cycle
    dt_state.previous_dipole_a_m2 = limited_dipole;

    // Set Output
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = sat_mask;
    dt_output.slew_mask = slew_mask;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.dipole_a_m2 = limited_dipole;

    return;

reject_sample:
    // Rejected sample handling
    dt_state.good = 0;
    dt_state.bad++;
    if (dt_state.bad >= dt_config.max_bad) {
        dt_state.mode = DT_FAULT;
    }

    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s.x = 0.0;
    dt_output.rate_t_s.y = 0.0;
    dt_output.rate_t_s.z = 0.0;
    dt_output.dipole_a_m2.x = 0.0;
    dt_output.dipole_a_m2.y = 0.0;
    dt_output.dipole_a_m2.z = 0.0;
    return;
